use std::{fs,path::Path};use genewars_core::cd_candidate::camera_cells_for_target;use genewars_runtime::{terrain_target::project_terrain_target,construction_site::classify_construction_site_with_footprint};fn main(){let a:Vec<_>=std::env::args().collect();let map=fs::read(Path::new(&a[1]).join("2500/map.bin")).unwrap();let camera=camera_cells_for_target(&map,19839,12927).unwrap();let mut seen=std::collections::BTreeSet::new();for y in (330..431).step_by(8){for x in (340..521).step_by(8){if let Ok(p)=project_terrain_target(&map,camera,[x,y]){let q=p.point.map(|v|(v&!255)|127);let c=classify_construction_site_with_footprint(&map,q,1,100,[0;2],|i|Ok(map[i as usize*14+8]==2)).unwrap();let d=(i32::from(q[0])-21119).pow(2)+(i32::from(q[1])-13439).pow(2);if c as u8==0&&d>256*256&&d<=1024*1024&&seen.insert(q){println!("screen {x} {y} point {q:?}");}}}}}